1	Frontier Core Library	[h1]Frontier Core Library[/h1]\nShared scripts and assets used by most Ironclad Frontier mods.\n\n[b]For players:[/b] just subscribe, other mods load it for you.\n[b]For modders:[/b] see the [url=https://example.com/wiki/frontier-core]wiki[/url].\n\n[table]\n[tr][th]Version[/th][th]Game version[/th][/tr]\n[tr][td]3.4[/td][td]1.9+[/td][/tr]\n[tr][td]3.3[/td][td]1.8[/td][/tr]\n[/table]	6	297197950	1999-09-25 23:53:56.071271+00
2	Brass Locomotives Expanded	[h1]Brass Locomotives Expanded[/h1]\n[img]https://example.com/banner.png[/img]\nTwelve new locomotives, from the tiny [i]Copper Kettle[/i] to the [b]Ironclad Behemoth[/b].\n\n[list]\n[*]Full interiors\n[*]Custom whistle sounds\n[*][u]Night lights[/u]\n[/list]\n\n[quote=Brassfang]Took two years. Worth it.[/quote]	11	145008265	1999-08-19 23:53:56.071271+00
3	Saloon Life Overhaul	Makes saloons busy again: card games, piano players and the odd brawl.\n\n[b]Requires[/b] Frontier Core Library and one item nobody registered yet (to show unknown dependencies).	16	374661958	1999-07-13 23:53:56.071271+00
4	Copper Mines Remastered	[h2]Overview[/h2]\nCopper Mines Remastered brings fresh mines remastered to Ironclad Frontier. Tested with the latest game update.\n\n[olist]\n[*]Subscribe\n[*]Enable it in the mod list\n[*]Start a new game[/olist]\n\n[noparse][b]This stays literal[/b][/noparse] [strike]old notes[/strike]	5	25748013	1999-06-06 23:53:56.071271+00
